// Local, user-exported observations. No uploads, save contents or student identifiers.
export const VISUAL_CHECKS=[['controls','Movement and jumps respond reliably'],['camera','Creature and hazards stay visible'],['language','Complete task text is readable and pieces are easy to tap'],['animation','Walk, strike, recoil and landing look natural'],['resume','Background/resume and saved task recovery work'],['sustained','At least 15 minutes of play remains comfortable']];
export function deviceReport(world,graphics,checks={},env={}){
 const nav=env.navigator||globalThis.navigator||{},win=env.window||globalThis.window||{},screen=win.screen||{};
 return {format:'maxima-device-report-v1',release:'0.54.0',exportedAt:new Date().toISOString(),device:{userAgent:nav.userAgent||'unknown',touchPoints:nav.maxTouchPoints||0,viewport:{width:win.innerWidth||0,height:win.innerHeight||0,dpr:win.devicePixelRatio||1},screen:{width:screen.width||0,height:screen.height||0}},graphics:{...graphics,adaptive:world.adaptiveResolution?.snapshot?.()||null},resources:world.performanceMonitor?.snapshot?.()||null,lifecycle:world.lifecycle?.snapshot?.()||null,observations:['explore','task','evolution'].map(p=>({recent:world.frameMetrics?.snapshot(p)||{samples:0},session:world.frameMetrics?.session(p)||{frames:0}})),visualChecks:Object.fromEntries(VISUAL_CHECKS.map(([id])=>[id,['pass','fail'].includes(checks[id])?checks[id]:'not-tested'])),limits:'RAF intervals observed during visible gameplay, not GPU timings. Device identity and physical-device status are not independently verified. Visual checks are player-reported. No performance certification is inferred.'};
}
